let events = SailPointISC_Events_CL | where TimeGenerated {TimeRange};
let aa = SailPointISC_AccountActivities_CL | where TimeGenerated {TimeRange};
let wf = SailPointISC_WorkflowHistory_CL | where TimeGenerated {TimeRange};
print
  Events = toscalar(events | count),
  FailedEvents = toscalar(events | where toupper(Status) in ("FAILED", "FAILURE", "ERROR") | count),
  AccountActivities = toscalar(aa | count),
  Workflows = toscalar(wf | count),
  LastEvent = toscalar(events | summarize max(TimeGenerated))
